// Require các app khác (các app này đều đã require './logger')
require('./app1');
require('./app2');
require('./app3');

// Require trực tiếp lại logger ở file check
const logger = require('./logger');

console.log('\n========================================');
console.log(`[CHECK RESULT] Giá trị initCount cuối cùng là: ${logger.getInitCount()}`);
console.log('========================================');

if (logger.getInitCount() === 1) {
    console.log('✅ CHỨNG MINH THÀNH CÔNG: Cơ chế cache module của CommonJS hoạt động chính xác (initCount = 1 dù được require ở nhiều nơi).');
} else {
    console.log('❌ LỖI: initCount khác 1, cơ chế cache chưa hoạt động đúng.');
}